CREATE FUNCTION public.support_create_contact(p_hash text,p_name text,p_subject text,p_kind text,p_text text,p_user uuid DEFAULT NULL,p_video_id text DEFAULT NULL,p_video_title text DEFAULT NULL,p_video_url text DEFAULT NULL,p_thumbnail text DEFAULT '') RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cid uuid; BEGIN IF p_hash !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'Invalid reference'; END IF; INSERT INTO public.contact_conversations(sender_hash,user_id,sender_name,subject,kind,video_id,video_title,video_url,thumbnail,admin_unread) VALUES(p_hash,p_user,p_name,p_subject,p_kind,p_video_id,p_video_title,p_video_url,p_thumbnail,0) RETURNING id INTO cid; INSERT INTO public.contact_messages(conversation_id,role,text) VALUES(cid,'sender',p_text); RETURN cid; END $$;
REVOKE ALL ON FUNCTION public.support_create_contact(text,text,text,text,text,uuid,text,text,text,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.support_create_contact(text,text,text,text,text,uuid,text,text,text,text) TO service_role;